using FrankenTui.Layout;
using FrankenTui.Widgets;

namespace FrankenTui.Demo.Showcase;

// Ported from Rust upstream screens (default initial state)

internal static class Screen23Intrinsic { public static IWidget Build(ShowcaseDemoState s) { var menu = ShowcaseSurface.Panel("Menu", string.Join("\n", "📊 Dashboard", "⚙️ Settings", "❓ Help", "🔔 Notifications", "👤 Profile")); var content = ShowcaseSurface.Panel("Content", "Current width: 72\nSidebar mode: Full sidebar mode (width >= 60)\n\nThe sidebar adapts to terminal width:\n• Narrow: icon-only (4 cols)\n• Wide: full labels (20 cols)\n\nTry resizing your terminal!"); var chart = ShowcaseSurface.Panel(null, string.Join("\n", "mode:", "┃", "┃ 21x", "┃", "┃", "┃", "────", "╭───", "│", "│ 21", "│", "│", "│", "│", "│", "│", "╰───", "└────")); return new StackWidget(LayoutDirection.Vertical, [(LayoutConstraint.Fixed(1), new ParagraphWidget(" Intrinsic Sizing Demo • Adaptive Sidebar (1/4)")), (LayoutConstraint.Fill(), new StackWidget(LayoutDirection.Horizontal, [(LayoutConstraint.Fixed(22), menu), (LayoutConstraint.Fill(), content), (LayoutConstraint.Fixed(8), chart)]))]); } }

