internal static class Screen24LayoutInspect { public static IWidget Build(ShowcaseDemoState s) { var inspector = ShowcaseSurface.Panel("Inspector", "Scenario: Flex Trio\nDetails: Vertical flex: Fixed + Min + Max\nStep: Constraints - Inspect min/max bounds\n\nOverlay: on   Tree: on\n\nKeys: n/p scenario  [/ ] step  o overlay\n\nFlexRoot  req 44x15  got 44x15  min 0x0\n  Fixed  req 44x3  got 44x3  min 0x3  max ∞x3\n  Min  req 44x4  got 44x7  min 0x4  max ∞x∞\n  Max  req 44x6  got 44x3  min 0x0  max ∞x6"); var tree = ShowcaseSurface.Panel("Tree", "FlexRoot req=44x15 got=44x15 min=0x0\n  Fixed req=44x3 got=44x3 min=0x3 max=∞x3\n  Min req=44x4 got=44x7 min=0x4 max=∞x∞\n  Max req=44x6 got=44x3 min=0x0 max=∞x6"); var layout = ShowcaseSurface.Panel("Layout", "Fixed 44x3 [0..∞ x 3..3]\n\nMin 44x4→44x7 [0..∞ x 4..∞]\n\nMax 44x6→44x3 [0..∞ x 0..6]"); return new StackWidget(LayoutDirection.Horizontal, [(LayoutConstraint.Fixed(40), inspector), (LayoutConstraint.Fill(), new StackWidget(LayoutDirection.Vertical, [(LayoutConstraint.Fixed(20), layout), (LayoutConstraint.Fill(), tree)]))]); } }


